    pub unsafe fn from_raw_conn(conn: *mut xcb_connection_t) -> Connection {
        assert!(!conn.is_null());

        #[cfg(not(feature = "xlib_xcb"))]
        return Connection {
            c: conn,
            event_ext_data: Vec::new(),
            error_ext_data: Vec::new(),
